local CrucibleMaker = {}
local PRODUCTS = {
    simple_clay_crucible = { name = "Preprosta glinena talilnica", clayCost = 2, time = 3, cost = 35, science = 18, happiness = 1, description = "Preprosta glinena talilnica za alkimiste." },
    firebrick_crucible = { name = "Šamotna talilnica", clayCost = 2, stoneCost = 1, time = 5, cost = 100, science = 32, happiness = 1, prestige = 2, description = "Šamotna talilnica za trgovce." },
    bronze_handle_crucible = { name = "Bronastorokavna talilnica", clayCost = 2, bronzeCost = 2, stoneCost = 1, time = 8, cost = 260, science = 48, happiness = 2, prestige = 5, description = "Bronastorokavna talilnica za plemiče." },
    silver_pour_crucible = { name = "Srebrnalivna talilnica", clayCost = 2, silverCost = 2, bronzeCost = 1, stoneCost = 1, time = 12, cost = 620, science = 62, happiness = 3, prestige = 13, description = "Srebrnalivna talilnica za visoke plemiče." },
    gold_rim_crucible = { name = "Zlatookrasna talilnica", clayCost = 3, goldCost = 2, silverCost = 1, bronzeCost = 1, stoneCost = 1, jewelCost = 1, time = 16, cost = 1400, science = 78, happiness = 5, prestige = 26, description = "Zlatookrasna talilnica z draguljem za visoko plemstvo." },
    royal_grand_crucible = { name = "Kraljevski veliki talilnica", clayCost = 4, goldCost = 3, silverCost = 2, bronzeCost = 1, stoneCost = 2, jewelCost = 2, pearlCost = 2, time = 23, cost = 3200, science = 92, happiness = 12, prestige = 56, description = "Velika kraljevska talilnica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    crucible_workshop = { name = "Talilniška delavnica", cost = { gold = 220, wood = 100, stone = 120, clay = 6 }, upkeep = 5, qualityBonus = 5 },
    refractory_loft = { name = "Ognjevarna podstrešje", cost = { gold = 800, wood = 240, stone = 280, bronze = 6, clay = 8 }, upkeep = 18, qualityBonus = 18 },
    master_crucible_atelier = { name = "Mojstrski talilniški atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_crucible_palace = { name = "Kraljevska talilniška palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
CrucibleMaker.clayStock = 16; CrucibleMaker.stoneStock = 14; CrucibleMaker.bronzeStock = 10; CrucibleMaker.silverStock = 6; CrucibleMaker.goldStock = 6; CrucibleMaker.jewelStock = 4; CrucibleMaker.pearlStock = 4
CrucibleMaker.productStock = {}; CrucibleMaker.buildings = {}; CrucibleMaker.maker = nil; CrucibleMaker.activeMaking = {}; CrucibleMaker.totalProducts = 0; CrucibleMaker.dayTimer = 0
function CrucibleMaker.init() CrucibleMaker.clayStock=16; CrucibleMaker.stoneStock=14; CrucibleMaker.bronzeStock=10; CrucibleMaker.silverStock=6; CrucibleMaker.goldStock=6; CrucibleMaker.jewelStock=4; CrucibleMaker.pearlStock=4; CrucibleMaker.productStock={}; CrucibleMaker.buildings={}; CrucibleMaker.maker=nil; CrucibleMaker.activeMaking={}; CrucibleMaker.totalProducts=0; CrucibleMaker.dayTimer=0; print("[CrucibleMaker] Royal Crucible Maker System initialized (6 products, 4 buildings)") end
function CrucibleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrucibleMaker.maker={name=n or ("Talilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Talilnikar najet: %s (spretnost: %d)",CrucibleMaker.maker.name,s),"success") end; return true end
function CrucibleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrucibleMaker.build(id) local ok,e=CrucibleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrucibleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrucibleMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrucibleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrucibleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and CrucibleMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.stoneCost and CrucibleMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.bronzeCost and CrucibleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and CrucibleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrucibleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrucibleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrucibleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrucibleMaker.buildings==0 then return false,"Potrebna talilniška delavnica" end; if not CrucibleMaker.maker then return false,"Potreben talilnikar" end; return true end
function CrucibleMaker.make(pt,qty) qty=qty or 1; local ok,e=CrucibleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then CrucibleMaker.clayStock=CrucibleMaker.clayStock-d.clayCost*qty end; if d.stoneCost then CrucibleMaker.stoneStock=CrucibleMaker.stoneStock-d.stoneCost*qty end; if d.bronzeCost then CrucibleMaker.bronzeStock=CrucibleMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then CrucibleMaker.silverStock=CrucibleMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrucibleMaker.goldStock=CrucibleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrucibleMaker.jewelStock=CrucibleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrucibleMaker.pearlStock=CrucibleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrucibleMaker.maker then t=math.max(1,t-math.floor(CrucibleMaker.maker.skill/13)) end; table.insert(CrucibleMaker.activeMaking,{id="crucible_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrucibleMaker.completeMaking(m) local q=1.0+(CrucibleMaker.getQualityBonus()/100); if CrucibleMaker.maker then q=q+(CrucibleMaker.maker.skill/150) end; q=math.min(2.4,q); CrucibleMaker.productStock[m.productType]=(CrucibleMaker.productStock[m.productType] or 0)+m.quantity; CrucibleMaker.totalProducts=CrucibleMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrucibleMaker.maker then CrucibleMaker.maker.itemsMade=CrucibleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrucibleMaker.maker.skill=math.min(100,CrucibleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Talilnica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crucible.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function CrucibleMaker.update(dt) if not _G.state then return end; CrucibleMaker.dayTimer=CrucibleMaker.dayTimer+dt; if CrucibleMaker.dayTimer>=30 then CrucibleMaker.dayTimer=0; for i=#CrucibleMaker.activeMaking,1,-1 do local m=CrucibleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrucibleMaker.completeMaking(m); table.remove(CrucibleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrucibleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrucibleMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrucibleMaker.getStats() return {clayStock=CrucibleMaker.clayStock,stoneStock=CrucibleMaker.stoneStock,bronzeStock=CrucibleMaker.bronzeStock,silverStock=CrucibleMaker.silverStock,goldStock=CrucibleMaker.goldStock,jewelStock=CrucibleMaker.jewelStock,pearlStock=CrucibleMaker.pearlStock,productStock=CrucibleMaker.productStock,numBuildings=#CrucibleMaker.buildings,hasMaker=CrucibleMaker.maker~=nil,makerName=CrucibleMaker.maker and CrucibleMaker.maker.name or "—",makerSkill=CrucibleMaker.maker and CrucibleMaker.maker.skill or 0,activeMaking=#CrucibleMaker.activeMaking,totalProducts=CrucibleMaker.totalProducts} end
return CrucibleMaker
